def _approval_allows(payload: object) -> bool:
    if not isinstance(payload, dict):
        return False
    if payload.get("action") != "accept":
        return False
    content = payload.get("content")
    return isinstance(content, dict) and content.get("decision") == "approve"


def _approval_denies(payload: object) -> bool:
    if not isinstance(payload, dict):
        return False
    if payload.get("action") != "accept":
        return False
    content = payload.get("content")
    return isinstance(content, dict) and content.get("decision") == "deny"


def _approval_invalid(payload: object) -> bool:
    if not isinstance(payload, dict):
        return True
    if payload.get("action") != "accept":
        return False
    content = payload.get("content")
    if not isinstance(content, dict):
        return True
    return content.get("decision") not in {"approve", "deny"}


def _approval_payload(payload: dict[str, Any]) -> dict[str, Any]:
    if "result" in payload:
        result = payload.get("result")
        return result if isinstance(result, dict) else {"action": "cancel"}
    if "error" in payload:
        return {"action": "cancel"}
    return {"action": "cancel"}


def _decision_source(action: str, source: str) -> str:
    if source == "policy":
        return f"policy-{action}"
    return f"{source}-{action}"


def _is_notification(message: dict[str, Any]) -> bool:
    return "method" in message and "id" not in message


def _is_request(message: dict[str, Any]) -> bool:
    return "method" in message and "id" in message


def _response_key(value: object) -> str | None:
    if value is None:
        return None
    return json.dumps(value, sort_keys=True, separators=(",", ":"))


def _command_argument(arguments: object) -> str | None:
    if not isinstance(arguments, Mapping):
        return None
    for key in ("command", "cmd", "shell_command", "shellCommand"):
        value = arguments.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    return None


def _has_saved_package_block(reasons: Sequence[object]) -> bool:
    return any(isinstance(reason, Mapping) and reason.get("code") == "saved_package_block" for reason in reasons)


def _package_reason_signals(reasons: Sequence[object]) -> tuple[RiskSignalV2, ...]:
    signals: list[RiskSignalV2] = []
    for reason in reasons:
        if not isinstance(reason, Mapping):
            continue
        code = _optional_text(reason.get("code")) or "package-risk"
        message = _optional_text(reason.get("message")) or code.replace("_", " ")
        severity = _package_signal_severity(_optional_text(reason.get("severity")))
        signals.append(
            RiskSignalV2(
                signal_id=f"supply-chain.{code}",
                category="supply_chain",
                severity=severity,
                confidence="strong" if severity in {"high", "critical"} else "likely",
                detector=_optional_text(reason.get("source")) or "guard.supply-chain",
                title=message,
                plain_reason=message,
                technical_detail=message,
                evidence_ref=None,
                redaction_level="summary",
                false_positive_hint=(
                    "Review the package request or add a scoped exception only for a verified false positive."
                ),
                advisory_id=None,
            )
        )
    return tuple(signals)


def _package_signal_severity(value: str | None) -> RiskSeverityLabel:
    match value:
        case "info":
            return "info"
        case "low":
            return "low"
        case "medium":
            return "medium"
        case "high":
            return "high"
        case "critical":
            return "critical"
        case _:
            return "medium"


def _optional_text(value: object) -> str | None:
    if isinstance(value, str) and value.strip():
        return value.strip()
    return None


def _now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _approval_observation_supported(proxy: RuntimeMcpGuardProxy) -> bool:
    return all(
        _APPROVAL_RISK_DEFAULTS.method_owned(proxy, name)
        for name in (
            "_capture_tool_call_authority",
            "_bind_tool_call_artifact",
            "_evaluate_tool_call_authority",
            "_resolve_tool_call_authority",
        )
    )


def _queue_approval_with_risk_analysis(
    proxy: RuntimeMcpGuardProxy,
    analysis: BoundApprovalRiskAnalysis | None,
    **kwargs: Any,
) -> tuple[dict[str, Any], dict[str, Any]]:
    queue = proxy._queue_approval_center_response
    if analysis is not None and _APPROVAL_RISK_DEFAULTS.method_supported(
        proxy, "_queue_approval_center_response", queue
    ):
        return queue(**kwargs, _risk_analysis=analysis)
    return queue(**kwargs)


def _build_approval_payload_with_risk_analysis(
    proxy: RuntimeMcpGuardProxy,
    analysis: BoundApprovalRiskAnalysis | None,
    artifact: Any,
    artifact_hash: str,
    tool_name: str,
    params: dict[str, Any],
    signals: tuple[str, ...],
    **kwargs: Any,
) -> dict[str, Any]:
    payload = proxy._build_artifact_payload
    if analysis is not None and _APPROVAL_RISK_DEFAULTS.method_supported(proxy, "_build_artifact_payload", payload):
        return payload(artifact, artifact_hash, tool_name, params, signals, **kwargs, _risk_analysis=analysis)
    return payload(artifact, artifact_hash, tool_name, params, signals, **kwargs)


def _approval_risk_summary(
    analysis: BoundApprovalRiskAnalysis | None,
    artifact: GuardArtifact,
    arguments: object,
) -> str:
    if type(analysis) is BoundApprovalRiskAnalysis and analysis.observe(artifact, arguments, consumer="summary"):
        return _tool_call_summary_for_signals(analysis.signals)
    return tool_call_risk_summary(artifact, arguments)


def _approval_risk_categories(
    analysis: BoundApprovalRiskAnalysis | None,
    artifact: GuardArtifact,
    arguments: object,
) -> tuple[str, ...]:
    if type(analysis) is BoundApprovalRiskAnalysis and analysis.observe(artifact, arguments, consumer="receipt"):
        return analysis.categories
    return tool_call_risk_categories(artifact, arguments)


